// frontend/src/components/WatchList.js

import React, { useContext, useEffect, useState } from "react";
import GeneralContext from "./GeneralContext";
import { Tooltip, Grow } from "@mui/material";
import {
  BarChartOutlined,
  KeyboardArrowDown,
  KeyboardArrowUp,
  MoreHoriz,
} from "@mui/icons-material";

import { DoughnutChart } from "./DoughnoutChart";
import Search from "./Search";

const WatchList = () => {
  const { watchlist, refreshWatchlist, openBuyWindow } =
    useContext(GeneralContext);

  useEffect(() => {
    refreshWatchlist();
  }, []);

  if (!watchlist) return <div>Loading watchlist...</div>;

  const data = {
    labels: watchlist.map((stock) => stock.name),
    datasets: [
      {
        label: "Price",
        data: watchlist.map((stock) => stock.price),
        backgroundColor: watchlist.map((s) =>
          s.changePct >= 0 ? "rgba(0, 200, 0, 0.4)" : "rgba(200, 0, 0, 0.4)"
        ),
        borderColor: watchlist.map((s) => (s.changePct >= 0 ? "green" : "red")),
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="watchlist-container">
      <Search />
      <div className="search-container">
        <span className="counts">{watchlist.length} / 50</span>
      </div>

      <ul className="list">
        {watchlist.map((stock, index) => (
          <WatchListItem
            stock={stock}
            key={index}
            openBuyWindow={openBuyWindow}
          />
        ))}
      </ul>

      <DoughnutChart data={data} />
    </div>
  );
};

export default WatchList;

const WatchListItem = ({ stock, openBuyWindow }) => {
  const [showActions, setShowActions] = useState(false);

  return (
    <li
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}>
      <div className="item">
        <p className={stock.changePct < 0 ? "down" : "up"}>{stock.name}</p>
        <div className="itemInfo">
          <span className="percent">{stock.changePct}%</span>
          {stock.changePct < 0 ? (
            <KeyboardArrowDown className="down" />
          ) : (
            <KeyboardArrowUp className="up" />
          )}
          <span className="price">₹{stock.price}</span>
        </div>
      </div>
      {showActions && (
        <WatchListActions uid={stock.symbol} openBuyWindow={openBuyWindow} />
      )}
    </li>
  );
};

const WatchListActions = ({ uid, openBuyWindow }) => (
  <span className="actions">
    <Tooltip title="Buy" arrow TransitionComponent={Grow}>
      <button className="buy" onClick={() => openBuyWindow(uid, "BUY")}>
        Buy
      </button>
    </Tooltip>

    <Tooltip title="Sell" arrow TransitionComponent={Grow}>
      <button className="sell" onClick={() => openBuyWindow(uid, "SELL")}>
        Sell
      </button>
    </Tooltip>

    <Tooltip title="Analytics" arrow TransitionComponent={Grow}>
      <button className="action">
        <BarChartOutlined className="icon" />
      </button>
    </Tooltip>

    <Tooltip title="More" arrow TransitionComponent={Grow}>
      <button className="action">
        <MoreHoriz className="icon" />
      </button>
    </Tooltip>
  </span>
);
